#!/bin/bash
# SPDX-License-Identifier: GPL-2.0
# Standalone ports offline OTA for legacy systems.
# User puts *.tar in /storage/roms/.update/, then run from Ports.

set -e

. /etc/profile
set_kill set "Offline Upgrade"

export XDG_RUNTIME_DIR=/var/run/0-runtime-dir
export WAYLAND_DISPLAY=wayland-1
export DISPLAY=:0.0

UPDATE_MARKER_DIR="/storage/.update"
UPDATE_ROMS_DIR="/storage/roms/.update"
REDIRECT_FILE="${UPDATE_MARKER_DIR}/redirect_part"
DISTRO_PREFIX="AURKNIX"
FLASH_FREE_MIN=$((5 * 1024 * 1024))
TMP_ASSET_DIR=$(mktemp -d -p /tmp)

cleanup() {
  stop_mpv
  rm -rf "${TMP_ASSET_DIR}"
}
trap cleanup EXIT

materialize_image() {
  local img="${1}"
  local dest="${TMP_ASSET_DIR}/${img}"
  [ -f "${dest}" ] && return 0
  case "${img}" in
    preparing-upgrade.png)
      base64 -d > "${dest}" <<'B64_PREPARING'

B64_PREPARING
      ;;
    deploy-success.png)
      base64 -d > "${dest}" <<'B64_SUCCESS'

B64_SUCCESS
      ;;
    deploy-failed.png)
      base64 -d > "${dest}" <<'B64_FAILED'

B64_FAILED
      ;;
    *)
      return 1
      ;;
  esac
}

show_image() {
  local img="${1}"
  set +e
  killall -9 mpv 2>/dev/null
  set -e
  materialize_image "${img}" || return 0
  if [ -f "${TMP_ASSET_DIR}/${img}" ]; then
    mpv --loop-file=inf --fullscreen --no-terminal "${TMP_ASSET_DIR}/${img}" >/dev/null 2>&1 &
  fi
}

stop_mpv() {
  killall -9 mpv 2>/dev/null || true
}

show_failure() {
  show_image "deploy-failed.png"
  sleep 5
  stop_mpv
}

block_device_for_path() {
  df "$1" 2>/dev/null | awk 'NR==2 {print $1}'
}

find_update_tar() {
  local tar pkg_prefix

  if [ -z "${HW_DEVICE}" ] || [ -z "${HW_ARCH}" ]; then
    echo "Error: HW_DEVICE or HW_ARCH not set (source /etc/profile)." >&2
    return 1
  fi

  pkg_prefix="${DISTRO_PREFIX}-${HW_DEVICE}.${HW_ARCH}-"
  tar=$(ls -1 "${UPDATE_ROMS_DIR}/${pkg_prefix}"*.tar 2>/dev/null | sort -r | head -n 1)

  if [ -z "${tar}" ]; then
    echo "Error: no OTA package matching ${pkg_prefix}*.tar in ${UPDATE_ROMS_DIR}" >&2
    echo "Available packages:" >&2
    ls -1 "${UPDATE_ROMS_DIR}"/*.tar 2>/dev/null | sed 's/^/  /' >&2 || true
    return 1
  fi

  printf '%s\n' "${tar}"
}

verify_checksum() {
  local tar_file="${1}"
  local checksum_file="${tar_file}.sha256"

  [ -f "${checksum_file}" ] || return 0

  local expected actual
  expected=$(awk '{print $1}' "${checksum_file}")
  actual=$(sha256sum "${tar_file}" | awk '{print $1}')
  [ "${expected}" = "${actual}" ]
}

prepare_redirect() {
  local update_tar="${1}"
  local roms_dev storage_dev

  if ! mountpoint -q /storage/roms 2>/dev/null; then
    echo "Error: /storage/roms is not mounted."
    return 1
  fi

  roms_dev=$(block_device_for_path "/storage/roms")
  storage_dev=$(block_device_for_path "/storage")
  if [ -z "${roms_dev}" ]; then
    echo "Error: could not resolve block device for /storage/roms."
    return 1
  fi

  case "${roms_dev}" in
    /dev/*) ;;
    *)
      echo "Error: /storage/roms is not backed by a block device (${roms_dev})."
      echo "Use an external SD card partition or free space on /storage/.update instead."
      return 1
      ;;
  esac

  if [ "${roms_dev}" = "${storage_dev}" ]; then
    echo "Error: /storage/roms uses the same partition as /storage."
    echo "Place the update package in ${UPDATE_MARKER_DIR} instead, or use external storage."
    return 1
  fi

  mkdir -p "${UPDATE_MARKER_DIR}" "${UPDATE_ROMS_DIR}"
  echo "${roms_dev}" > "${REDIRECT_FILE}"
  sync

  echo "Update package: ${update_tar}"
  echo "Redirect device: ${roms_dev}"
  echo "Marker file: ${REDIRECT_FILE}"
  return 0
}

resolve_kernel_name() {
  local name

  for name in KERNEL kernel.img Image; do
    if [ -f "/flash/${name}" ]; then
      printf '%s\n' "${name}"
      return 0
    fi
  done

  if [ -f /flash/extlinux/extlinux.conf ]; then
    name=$(awk '/^[[:space:]]*LINUX[[:space:]]/ {gsub(/^\//, "", $2); print $2; exit}' \
      /flash/extlinux/extlinux.conf)
    if [ -n "${name}" ] && [ -f "/flash/${name}" ]; then
      printf '%s\n' "${name}"
      return 0
    fi
  fi

  printf '%s\n' "KERNEL"
}

find_kernel_tar_member() {
  local tar_file="${1}"
  local prefer_name="${2}"
  local member candidate

  if [ -n "${prefer_name}" ]; then
    member=$(tar -tf "${tar_file}" 2>/dev/null | grep -E "/target/${prefer_name}$" | head -n 1)
    if [ -n "${member}" ]; then
      printf '%s\n' "${member}"
      return 0
    fi
  fi

  for candidate in KERNEL kernel.img Image; do
    member=$(tar -tf "${tar_file}" 2>/dev/null | grep -E "/target/${candidate}$" | head -n 1)
    if [ -n "${member}" ]; then
      printf '%s\n' "${member}"
      return 0
    fi
  done

  return 1
}

update_flash_kernel() {
  local tar_file="${1}"
  local tmpdir kernel_name kernel_member md5_member kernel_src
  local kernel_dir package_dir md5_file check_file
  local flash_target flash_free old_kernel new_kernel tmp_size

  if ! mountpoint -q /flash 2>/dev/null; then
    echo "Error: /flash is not mounted."
    return 1
  fi

  kernel_name=$(resolve_kernel_name)
  flash_target="/flash/${kernel_name}"
  if [ ! -f "${flash_target}" ]; then
    echo "Error: target kernel ${flash_target} not found."
    return 1
  fi

  kernel_member=$(find_kernel_tar_member "${tar_file}" "${kernel_name}") || {
    echo "Error: KERNEL not found inside OTA package."
    return 1
  }
  kernel_name=$(basename "${kernel_member}")
  flash_target="/flash/${kernel_name}"

  tmpdir=$(mktemp -d -p "$(dirname "${tar_file}")")
  md5_member="${kernel_member}.md5"
  if tar -tf "${tar_file}" 2>/dev/null | grep -Fx "${md5_member}" >/dev/null; then
    if ! tar -xf "${tar_file}" -C "${tmpdir}" "${kernel_member}" "${md5_member}" 2>/dev/null; then
      rm -rf "${tmpdir}"
      echo "Error: failed to extract ${kernel_member} from ${tar_file}."
      return 1
    fi
  elif ! tar -xf "${tar_file}" -C "${tmpdir}" "${kernel_member}" 2>/dev/null; then
    rm -rf "${tmpdir}"
    echo "Error: failed to extract ${kernel_member} from ${tar_file}."
    return 1
  fi

  kernel_src="${tmpdir}/${kernel_member}"
  if [ ! -f "${kernel_src}" ]; then
    rm -rf "${tmpdir}"
    echo "Error: extracted kernel file is missing."
    return 1
  fi

  # KERNEL.md5 lists "target/KERNEL" relative to the OTA package root (see
  # scripts/image).  init replaces that path because UPDATE_DIR is the target/
  # folder itself; here we keep the archive layout and verify from package root.
  if [ -f "${tmpdir}/${md5_member}" ]; then
    kernel_dir=$(dirname "${kernel_src}")
    package_dir=$(dirname "${kernel_dir}")
    md5_file="${kernel_dir}/${kernel_name}.md5"
    check_file="${package_dir}/${kernel_name}.check.md5"

    cp "${md5_file}" "${check_file}"
    if ! (cd "${package_dir}" && md5sum -sc "${kernel_name}.check.md5"); then
      rm -f "${check_file}"
      rm -rf "${tmpdir}"
      echo "Error: kernel md5 verification failed."
      return 1
    fi
    rm -f "${check_file}"
  fi

  flash_free=$(df /flash/ | awk '/[0-9]%/{print $4}')
  flash_free=$((flash_free * 1024))
  old_kernel=$(stat -t "${flash_target}" | awk '{print $2}')
  new_kernel=$(stat -Lt "${kernel_src}" | awk '{print $2}')
  tmp_size=$((old_kernel + flash_free - new_kernel))
  if [ "${tmp_size}" -lt "${FLASH_FREE_MIN}" ]; then
    rm -rf "${tmpdir}"
    echo "Error: not enough free space on /flash to replace ${kernel_name}."
    return 1
  fi

  if ! mount -o remount,rw /flash; then
    rm -rf "${tmpdir}"
    echo "Error: could not remount /flash read-write."
    return 1
  fi

  echo "Updating ${flash_target} from OTA package..."
  rm -f "${flash_target}"
  if ! cp "${kernel_src}" "${flash_target}"; then
    mount -o remount,ro /flash 2>/dev/null || true
    rm -rf "${tmpdir}"
    echo "Error: failed to write ${flash_target}."
    return 1
  fi

  sync

  if ! grep -q 'disk=FILE' /proc/cmdline 2>/dev/null; then
    mount -o remount,ro /flash 2>/dev/null || true
  fi

  rm -rf "${tmpdir}"
  echo "Kernel update on /flash completed."
  return 0
}

echo "=== AURKNIX Offline Upgrade (Ports) ==="

show_image "preparing-upgrade.png"

update_tar=$(find_update_tar) || {
  show_failure
  exit 1
}

if ! verify_checksum "${update_tar}"; then
  echo "Error: checksum verification failed for ${update_tar}"
  rm -f "${REDIRECT_FILE}"
  show_failure
  exit 1
fi

if ! prepare_redirect "${update_tar}"; then
  rm -f "${REDIRECT_FILE}"
  show_failure
  exit 1
fi

if ! update_flash_kernel "${update_tar}"; then
  rm -f "${REDIRECT_FILE}"
  show_failure
  exit 1
fi

echo "============================================="
echo "Offline upgrade is ready."
echo "Reboot the device to apply the system update."
echo "============================================="

show_image "deploy-success.png"
sleep 5
stop_mpv
